// جيد — allowlist للمضيفين + منع عناوين داخلية + تعطيل التحويلات
const ALLOWED_HOSTS = ['images.trusted-cdn.com'];
app.post('/api/fetch-image', async (req, res) => {
  const url = new URL(req.body.url);
  if (!ALLOWED_HOSTS.includes(url.hostname)) {
    return res.status(400).json({ error: 'مضيف غير مسموح' });
  }
  const response = await fetch(url, { redirect: 'manual' }); // بلا تتبع تحويلات
  res.send(await response.buffer());
});

