// مثال توثيق بسيط لسياسة دعم النسخ
const apiVersions = {
  v1: { status: 'deprecated', sunsetDate: '2026-01-01', securityPatches: false },
  v2: { status: 'active', securityPatches: true },
};

// Middleware يرفض النسخ منتهية الدعم بدل تركها تعمل بصمت
app.use('/api/v1', (req, res, next) => {
  if (apiVersions.v1.status === 'deprecated' && isPastSunset()) {
    return res.status(410).json({ error: 'هذه النسخة لم تعد مدعومة، استخدم v2' });
  }
  next();
});

