app.get('/api/x', async (req, res) => {
  const x = await db.x.findUniqueOrThrow({ where: { id: req.params.id } });
  res.json(x);
}); // استثناء غير ملتقَط = 500 مع stack trace كامل للمستخدم

// جيد
app.get('/api/x', async (req, res) => {
  try {
    const x = await db.x.findUniqueOrThrow({ where: { id: req.params.id } });
    res.json(x);
  } catch (err) {
    logger.error({ err, requestId: req.id });
    res.status(404).json({ error: 'غير موجود', requestId: req.id });
  }
});

async function transferFunds(fromId, toId, amount) {
  return db.$transaction(async (tx) => {
    const from = await tx.account.update({
      where: { id: fromId },
      data: { balance: { decrement: amount } },
    });
    if (from.balance < 0) throw new Error('رصيد غير كافٍ'); // تراجع كامل تلقائي
    await tx.account.update({ where: { id: toId }, data: { balance: { increment: amount } } });
  });
}

